<?php use App\Core\Helpers as H;?><div style="padding:8px 32px"><h2>Sponsored picks</h2><div><?php foreach($data['paid_promos']??[] as $promo):?><div style="display:inline-block;vertical-align:top;width:220px;margin:8px;padding:12px;border:1px solid #ddd"><div style="font-size:11px;font-weight:bold;text-transform:uppercase">Sponsored</div><a href="<?=H::e(H::baseUrl().'/promo/click/'.$promo['click_token'])?>"><?php if($promo['image']):?><img style="max-width:100%;height:auto" src="<?=H::e(H::assetUrl($promo['image']))?>" alt=""><?php endif;?><strong><?=H::e($promo['title'])?></strong></a><?php if($promo['type']==='product'):?><div><?=H::money($promo['price'])?></div><?php endif;?></div><?php endforeach;?></div></div>
